if(webhook&&raw.trustSource!=='trusted-lan-ui')throw Error('Trusted LAN backend transport required');
if(!['inspect','list','verify'].includes(request.action)&&(!Number.isSafeInteger(request.assetId)||request.assetId<=0))throw Error('Positive exact assetId required');
if(request.action==='regenerate'&&(typeof request.prompt!=='string'||!request.prompt.trim()||request.prompt.length>5000))throw Error('Nonblank regeneration prompt required (maximum 5000 characters)');
if(request.action==='enhance_prompt'){if(webhook&&(typeof request.enhancementModel!=='string'||!request.enhancementModel||request.enhancementModel.length>256||/[\x00-\x1f]/.test(request.enhancementModel)))throw Error('Backend-validated enhancement model required');if(!webhook&&!request.enhancementModel)request.enhancementModel='qwen3.8:latest';}
return [{json:request}];

const request=$('Review Request').first().json;
if (String($json.id)!==request.JobID) throw new Error('JobID does not identify a production row');
if (!['Queued', 'Qued'].includes($json.Status)) throw new Error('Production is not fully dispatched (expected Queued or legacy Qued)');

if($json.Type!=='Review'||$json.Working===true||$json.LastError)throw Error('Only idle production Review rows without errors are reviewable');

return [{json:request}];

const req=$('Review Request').first().json;
const parent=$('Get Production').first().json;
const jobs=$input.all().map(i=>i.json).filter(j=>j.id).sort((a,b)=>a.id-b.id);
if(!jobs.length||jobs.length>64)throw Error('No required assets or asset limit exceeded');
if(jobs.some(j=>String(j.JobID)!==req.JobID)||new Set(jobs.map(j=>j.id)).size!==jobs.length)throw Error('Asset linkage mismatch or duplicate');
const parse=v=>{const p=typeof v==='string'?JSON.parse(v):v;if(!p||typeof p!=='object'||Array.isArray(p))throw Error('Invalid dependency/Params object');return p;};
const validUrl=u=>typeof u==='string'&&/^http:\/\/10\.0\.0\.157:8188\/view\?[^\s#]+$/.test(u)&&/(?:\?|&)filename=[^&]+/.test(u);
let ready=parent.Type==='Review'&&parent.Working!==true&&jobs.every(j=>j.Completed===true&&j.Working!==true&&!j.LastError&&validUrl(j.URL)&&['Text to image','Image to video','FLF to video'].includes(j.type));
let readinessReason='';try{
const scenes=typeof parent.Scenes==='string'?JSON.parse(parent.Scenes):parent.Scenes;
if(!Array.isArray(scenes)||!scenes.length||scenes.some(s=>!s||typeof s.scene_id!=='string')||new Set(scenes.map(s=>s.scene_id)).size!==scenes.length)throw Error('Missing/ambiguous source scene contract');
const sourceById=new Map(scenes.map(s=>[s.scene_id,s]));
const sourceType=s=>({'text_to_image':'Text to image','t2i':'Text to image','image_to_video':'Image to video','i2v':'Image to video','flf_to_video':'FLF to video','flf2v':'FLF to video'})[String(s.type||s.Type||'').trim().toLowerCase().replace(/[\s-]+/g,'_')];
function sourceIds(id){if(sourceById.has(id))return [id];const parts=id.split('_');for(let i=1;i<parts.length;i++){const a=parts.slice(0,i).join('_'),b=parts.slice(i).join('_');if(sourceById.has(a)){if(sourceById.has(b))return [a,b];const m=a.match(/^(.*?_)(\d+)$/);if(m&&sourceById.has(m[1]+b))return [a,m[1]+b];}}const m=id.match(/^(.+?)([A-Za-z])$/);return m&&sourceById.has(m[1])?[m[1]]:[];}
const groups=new Map(),covered=new Set();
for(const j of jobs){const id=JSON.parse(j.Params).scene_id;if(typeof id!=='string')throw Error('Missing scene ID');if(!groups.has(id))groups.set(id,[]);groups.get(id).push(j);}
for(const [id,assets] of groups){const ids=sourceIds(id);if(!ids.length)throw Error('Unresolved source scene '+id);const types=new Set(ids.map(id=>sourceType(sourceById.get(id))));if(types.size!==1||types.has(undefined))throw Error('Unsupported/ambiguous source scene type '+id);ids.forEach(id=>covered.add(id));const type=[...types][0];const slots=type==='Text to image'?[['Text to image','static']]:type==='Image to video'?[['Text to image','source'],['Image to video','static']]:[['Text to image','first'],['Text to image','last'],['FLF to video','static']];if(assets.length!==slots.length||slots.some(([type,role])=>assets.filter(a=>a.type===type&&JSON.parse(a.Params).frame_role===role).length!==1))throw Error('Required source scene asset bundle incomplete '+id);}
if(scenes.some(s=>!covered.has(s.scene_id)))throw Error('Required source scene assets missing');
 for(const j of jobs){const d=parse(j.Dependencies),p=parse(j.Params);if(d.version!==1||!Array.isArray(d.inputs)||!p.scene_id||!p.frame_role)throw Error('Missing scene/frame provenance for asset '+j.id);
 const roles=j.type==='Text to image'?[]:j.type==='Image to video'?['source']:j.type==='FLF to video'?['first','last']:null;
 if(!roles||roles.length!==d.inputs.length||new Set(d.inputs.map(e=>e.role)).size!==roles.length)throw Error('Required frame bindings mismatch '+j.id);
 for(const role of roles){const e=d.inputs.find(e=>e.role===role);const a=jobs.find(a=>a.id===e?.rowId);if(!e||!Number.isSafeInteger(e.rowId)||!a||a.id===j.id||a.type!=='Text to image'||a.Completed!==true||a.Working===true||a.LastError||!validUrl(a.URL))throw Error('Missing/failed prerequisite for asset '+j.id);const ap=parse(a.Params);if(ap.scene_id!==p.scene_id||ap.frame_role!==role)throw Error('Prerequisite scene/role mismatch '+j.id);}
 }
}catch(e){ready=false;readinessReason=e.message;}
const outputs=jobs.map(j=>({id:j.id,type:j.type,URL:j.URL,Completed:j.Completed,Working:j.Working,LastError:j.LastError??null,Params:j.Params,prompt:j.prompt,Dependencies:j.Dependencies,ExecutionID:j.ExecutionID??null,RequestKey:j.RequestKey??null}));
if(req.action!=='inspect'){
 // Readability is checked by the browser preview, not a full-file cryptographic download.

}
const production={id:parent.id,Type:parent.Type??null,Status:parent.Status,Working:parent.Working??null,Completed:parent.Completed??null,LastError:parent.LastError??null,Script:parent.Script??null,Scenes:parent.Scenes??null};
if(parent.LastError)ready=false;
const snapshot=JSON.stringify({version:2,production,outputs});
return [{json:{...req,ready,readinessReason,snapshot,outputs}}];

const current=$('Capture Output Snapshot').first().json;
const previous=$input.all().map(i=>i.json).filter(r=>r.JobID===current.JobID);
if(previous.length>1)throw Error('Ambiguous review state');
const old=previous[0];let saved=[];try{saved=JSON.parse(old?.Outputs||'[]');}catch{throw Error('Corrupt persisted review state');}
if(!Array.isArray(saved)||saved.some(o=>!current.outputs.some(c=>c.id===o.id)))throw Error('Missing previously enrolled required asset; do not shrink the review gate');
const liveOwner=$('Get Active Owners').all().some(i=>(!i.json.workflow||String(i.json.workflow)==='MZK3Pv01FHqZbooz')&&current.outputs.some(o=>o.id===Number(i.json.rowId)));if(liveOwner){current.ready=false;current.readinessReason='Active generation owner';}
if(['approve_asset','reject_asset','regenerate','enhance_prompt'].includes(current.action)&&liveOwner)throw Error('Active generation owner; review mutation blocked');
const mutation=['approve_asset','reject_asset','regenerate'].includes(current.action),guarded=mutation||current.action==='enhance_prompt';
if(['approve','reject'].includes(current.action))throw Error('Whole-job decisions disabled: decide each asset');
if(guarded&&(!old||old.Snapshot!==current.snapshot||current.expectedSnapshot!==current.snapshot))throw Error('Decision snapshot differs from inspected outputs; list again');
if(current.action==='enhance_prompt'&&(!current.ready||!current.outputs.some(o=>o.id===current.assetId)||typeof current.prompt!=='string'||!current.prompt.trim()||current.prompt.length>20000))throw Error('Nonblank draft and ready selected asset required for enhancement');
const assetSnapshot=o=>JSON.stringify({production:JSON.parse(current.snapshot).production,asset:o});
const outputs=current.outputs.map(o=>{const prior=saved.find(p=>p.id===o.id);const matched=prior?.review?.snapshot===assetSnapshot(o);return {...o,review:matched?prior.review:{state:'pending',snapshot:assetSnapshot(o),actor:'',at:'',reason:''},history:Array.isArray(prior?.history)?prior.history:[]};});
if(mutation){
 if(!current.ready)throw Error('All current required assets must be complete and dependency-valid');
 const selected=outputs.find(o=>o.id===current.assetId);if(!selected)throw Error('Selected asset is not required by this job');
 if(['approve_asset','reject_asset'].includes(current.action))selected.review={state:current.action==='approve_asset'?'approved':'rejected',snapshot:assetSnapshot(current.outputs.find(o=>o.id===current.assetId)),actor:current.approvedBy,at:new Date().toISOString(),reason:current.reason||''};
 if(['save_prompt','regenerate'].includes(current.action)){
  if(typeof current.prompt!=='string'||!current.prompt.trim()||current.prompt.length>5000)throw Error('Nonblank regeneration prompt required (maximum 5000 characters)');
  selected.history=[...selected.history,{...selected,history:undefined,supersededAt:new Date().toISOString(),actor:current.approvedBy,submittedPrompt:current.prompt}].slice(-32);
  const affected=new Set([selected.id]);let changed=true;while(changed){changed=false;for(const o of outputs){const d=JSON.parse(o.Dependencies);if(d.inputs.some(e=>affected.has(e.rowId))&&!affected.has(o.id)){affected.add(o.id);changed=true;}}}
  for(const o of outputs)if(affected.has(o.id)){if(o.id!==selected.id)o.history=[...o.history,{...o,history:undefined,supersededAt:new Date().toISOString(),actor:current.approvedBy,reason:'Prerequisite image regeneration invalidated this dependent output'}].slice(-32);o.review={state:'pending',snapshot:'',actor:current.approvedBy,at:new Date().toISOString(),reason:'Prompt/output superseded; review required'};}
 }
}
const allApproved=current.ready&&outputs.length>0&&outputs.every(o=>o.review.state==='approved');
const State=allApproved?'approved':outputs.some(o=>o.review.state==='rejected')?'rejected':'pending';
return [{json:{...current,State,Snapshot:current.snapshot,Outputs:JSON.stringify(outputs),outputs,ReviewedAt:mutation?new Date().toISOString():(old?.ReviewedAt||''),Reason:current.reason||'',ApprovedBy:mutation?current.approvedBy:(old?.ApprovedBy||''),FinalGenerationAllowed:false,assemblyAvailable:false,nextStep:allApproved?'Approved — next step not configured; final assembly is unavailable.':'Waiting for every current required asset approval',approvedCount:outputs.filter(o=>o.review.state==='approved').length,requiredCount:outputs.length}}];

const r=$('Evaluate Manual Decision').first().json;
const jobs=$('Get Generation Jobs').all().map(i=>i.json).filter(j=>j.id);
const owners=$('Get Active Owners').all().map(i=>i.json).filter(j=>j.id||j.rowId);
if(r.action!=='regenerate'||!r.ready)throw Error('Explicit ready asset regeneration required');
const selected=jobs.find(j=>j.id===r.assetId);if(!selected)throw Error('Selected asset missing');
const affected=new Set([selected.id]);let changed=true;while(changed){changed=false;for(const j of jobs){const d=JSON.parse(j.Dependencies);if(d.inputs.some(e=>affected.has(e.rowId))&&!affected.has(j.id)){affected.add(j.id);changed=true;}}}
if(jobs.some(j=>affected.has(j.id)&&(j.Working===true||String(j.JobID)!==r.JobID))||owners.some(o=>(!o.workflow||String(o.workflow)==='MZK3Pv01FHqZbooz')&&affected.has(Number(o.rowId))))throw Error('Active generation owner: regeneration refused without clearing locks');
return jobs.filter(j=>affected.has(j.id)).map(j=>({json:{...j,prompt:j.id===selected.id?r.prompt:j.prompt,Completed:false,Working:false,URL:'',LastError:j.id===selected.id?'Review regeneration pending explicit dispatch':'Source image superseded; explicit regeneration required after prerequisites complete',_expected:j,_selected:j.id===selected.id}}));

const r=$('Evaluate Manual Decision').first().json,parent=$('Get Production').first().json;
if(r.action!=='enhance_prompt'||r.ready!==true||typeof r.prompt!=='string'||!r.prompt.trim()||r.prompt.length>20000)throw Error('A ready selected asset and nonblank editable draft are required');
const selected=r.outputs.find(o=>o.id===r.assetId);if(!selected||!['Text to image','Image to video','FLF to video'].includes(selected.type))throw Error('Unsupported selected enhancement asset');
const p=JSON.parse(selected.Params),dependencies=JSON.parse(selected.Dependencies),scenes=typeof parent.Scenes==='string'?JSON.parse(parent.Scenes):parent.Scenes;
const byId=new Map(scenes.map(s=>[s.scene_id,s]));
function sourceIds(id){if(byId.has(id))return [id];const parts=id.split('_');for(let i=1;i<parts.length;i++){const a=parts.slice(0,i).join('_'),b=parts.slice(i).join('_');if(byId.has(a)){if(byId.has(b))return [a,b];const m=a.match(/^(.*?_)(\d+)$/);if(m&&byId.has(m[1]+b))return [a,m[1]+b];}}const m=id.match(/^(.+?)([A-Za-z])$/);return m&&byId.has(m[1])?[m[1]]:[];}
const source=sourceIds(p.scene_id).map(id=>byId.get(id));if(!source.length)throw Error('Cannot resolve exact source scene for enhancement');
const sourceNarration=source.map(s=>s.voiceover||'').join('\n');
const framePrerequisites=dependencies.inputs.map(e=>{const o=r.outputs.find(o=>o.id===e.rowId);if(!o)throw Error('Missing literal frame prerequisite');return {role:e.role,assetId:o.id,type:o.type,Params:o.Params,positivePrompt:o.prompt};});
const protectedText=[...source.flatMap(s=>[s.voiceover,...(Array.isArray(s.dialogue)?s.dialogue:[])]).filter(v=>typeof v==='string'&&v&&r.prompt.includes(v)),...(r.prompt.match(/"[^"\n]{1,500}"/g)||[])];
const data={asset:{assetId:selected.id,type:selected.type,sceneId:p.scene_id,frameRole:p.frame_role,Params:selected.Params,Dependencies:selected.Dependencies},draft:r.prompt,currentPositivePrompt:selected.prompt,sourceNarration,sourceScenes:source,sourceScript:parent.Script,framePrerequisites,protectedText};
const requestPrompt=JSON.stringify(data);if(requestPrompt.length>64000)throw Error('Enhancement context exceeds safe input limit');
return [{json:{enhancementModel:r.enhancementModel,JobID:r.JobID,assetId:selected.id,assetType:selected.type,beforePrompt:r.prompt,sourceNarration,protectedText,snapshot:r.snapshot,requestPrompt}}];

const context=$('Build Prompt Enhancement Context').first().json,raw=$input.first().json;
if(raw.error||typeof raw.text!=='string'||!raw.text.trim())throw Error('Prompt enhancement failed or returned empty output; original draft is unchanged');
let result;try{result=JSON.parse(raw.text);}catch{throw Error('Enhancement returned invalid JSON; original draft is unchanged');}
if(!result||Array.isArray(result)||Object.keys(result).sort().join(',')!=='assetType,enhancedPrompt,sourceNarration')throw Error('Enhancement output schema invalid; original draft is unchanged');
if(result.assetType!==context.assetType||result.sourceNarration!==context.sourceNarration)throw Error('Enhancement changed protected asset type or source narration; original draft is unchanged');
if(typeof result.enhancedPrompt!=='string'||!result.enhancedPrompt.trim()||result.enhancedPrompt.length>20000||result.enhancedPrompt.trim()===context.beforePrompt.trim()||result.enhancedPrompt.includes('```')||/^error\s*:/i.test(result.enhancedPrompt.trim()))throw Error('Enhancement did not return a valid changed prompt; original draft is unchanged');
if(context.protectedText.some(text=>!result.enhancedPrompt.includes(text)))throw Error('Enhancement altered quoted wording or narration already present in the draft; original draft is unchanged');
return [{json:{JobID:context.JobID,assetId:context.assetId,assetType:context.assetType,beforePrompt:context.beforePrompt,enhancedPrompt:result.enhancedPrompt.trim(),sourceNarration:context.sourceNarration,snapshot:context.snapshot,generationDispatched:false,persisted:false}}];
